    needAction: A.filter(a => a.dataStatus && a.dataStatus !== 'Verified').length, critHigh: openExc.filter(x => ['Critical', 'High'].includes(x.severity)).length,
    pmOverdue: A.filter(a => a.pmStatus === 'Overdue'), pmDue: A.filter(a => a.pmStatus === 'Due in 14 Days'), pmNone: trucks.filter(a => a.pmStatus === 'Not Scheduled').length,
    open, oldestOpen: open[0]?.daysOpen ?? '', spendYTD: svc.filter(s => String(s.serviceDate).startsWith(todayISO().slice(0, 4))).reduce((t, s) => t + num(s.amount), 0),
    avgHrs: withHrs.length ? withHrs.reduce((t, a) => t + a.avgHrsWk, 0) / withHrs.length : '', hrsTrucks: withHrs.length,
    ops, opActive: ops.filter(o => o.status === 'Current' || /^Expiring/.test(o.status)), opExpired: ops.filter(o => o.status === 'Expired'), opExpiring: ops.filter(o => /^Expiring/.test(o.status)), opCheck: ops.filter(o => o.status === 'Check Dates' || o.status === 'Missing Expiry'),
    exc, openExc, bySite, mix, leases: A.filter(a => ['Active', 'Ending in 90 Days'].includes(a.leaseStatus)), leaseMonthly: A.reduce((t, a) => t + a.leaseMonthly, 0), leaseRemaining: A.reduce((t, a) => t + num(a.leaseRemaining), 0), leaseMissing: A.filter(a => a.leaseStatus === 'Missing Data').length,
