ATL_SRC.push(['@atl/views/trucksection.js', 0, `// "Trucks — on-time rate & outbound hold times" on the customer scorecards (Electrolit, WestRock): inbound and outbound
// shown apart, each with its own variance section (arrival vs appointment from the dock schedule). K = truckStats().
import { esc, fmtPct, fmtNum, fmtTime } from '@atl/util.js';
import { kpi } from '@atl/ui.js';

const pct = (v, d = 1) => (typeof v === 'number' ? fmtPct(v, d) : '—');
const mins = v => (typeof v === 'number' ? (Math.abs(v) >= 60 ? \`\${v < 0 ? '−' : ''}\${Math.floor(Math.abs(v) / 60)} h \${String(Math.round(Math.abs(v) % 60)).padStart(2, '0')} m\` : \`\${v < 0 ? '−' : ''}\${Math.round(Math.abs(v))} min\`) : '—');
const signed = v => (typeof v === 'number' ? \`\${v > 0 ? '+' : v < 0 ? '−' : ''}\${mins(Math.abs(v))}\` : '—');
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(2, 4)}\` : '');
const tiles = list => \`<div class="xl-tiles q elx-tiles" style="grid-template-columns:repeat(\${Math.min(5, list.length)}, minmax(0, 1fr))">\${list.join('')}</div>\`;
const th = cols => \`<thead><tr>\${cols.map(c => \`<th>\${c}</th>\`).join('')}</tr></thead>\`;
const logLink = (id, links) => (links === false ? esc(id) : \`<a href="#/log/trucks?ids=\${encodeURIComponent(id)}">\${esc(id)}</a>\`);

/** One direction: headline tiles, then its variance section (summary tiles + bands). */
function block(D, dir, cfg) {
  const inb = dir === 'In', w = cfg.onTimeMin;
  if (!D.n) return \`<div class="trk-dir"><h4 class="trk-h">\${inb ? 'Inbound' : 'Outbound'} trucks</h4><p class="muted">No \${inb ? 'inbound' : 'outbound'} loads in this period.</p></div>\`;
  const head = inb
    ? [kpi('On time', pct(D.onTime), \`\${D.rated} with an appointment · arrived early or within \${w} min\`, typeof D.onTime === 'number' ? 'good' : ''),
      kpi('Late', pct(D.late), \`more than \${w} min after the appointment\`, D.late ? 'warn' : ''),
      kpi('Arrived early', pct(D.earlyArrivals), \`more than \${w} min before — counted on time\`),
      kpi('Average time on site', mins(D.avgSite), \`\${D.n} load\${D.n === 1 ? '' : 's'}\${D.unrated ? \` · \${D.unrated} with no appointment\` : ''}\`)]
    : [kpi('On time', pct(D.onTime), \`\${D.rated} with an appointment · within ±\${w} min\`, typeof D.onTime === 'number' ? 'good' : ''),
      kpi('Early', pct(D.early), \`more than \${w} min before the appointment\`),
      kpi('Late', pct(D.late), \`more than \${w} min after\`, D.late ? 'warn' : ''),
      kpi('Average time on site', mins(D.avgSite), \`\${D.n} load\${D.n === 1 ? '' : 's'}\${D.unrated ? \` · \${D.unrated} with no appointment\` : ''}\`),
      kpi(\`Held > \${fmtNum(cfg.holdMin / 60, 1)} h\`, pct(D.pctHeld), \`\${D.held} of \${D.heldN} · average hold \${mins(D.avgHold)}\`, D.held ? 'warn' : '')];
  const max = Math.max(1, ...D.bands.map(b => b.n));
  const variance = D.rated ? \`<div class="trk-var">
      <h5>\${inb ? 'Inbound' : 'Outbound'} variance <small>arrival vs appointment · + late, − early</small></h5>
      \${tiles([kpi('Average variance', signed(D.avgVar), \`median \${signed(D.median)}\`, typeof D.avgVar === 'number' && D.avgVar > w ? 'warn' : ''),
        kpi('Within the window', pct(D.within), \`±\${w} min of the appointment\`),
        kpi('Average when early', typeof D.avgEarly === 'number' ? mins(D.avgEarly) : '—', 'how far ahead early trucks came'),
        kpi('Average when late', typeof D.avgLate === 'number' ? mins(D.avgLate) : '—', 'how far behind late trucks came', D.avgLate ? 'warn' : '')])}
      <div class="xl-otif-wrap"><table class="xl-otif trk-bands">\${th(['Variance', 'Loads', 'Share', ''])}<tbody>\${D.bands.map(b => {
        const tone = /late/.test(b.label) ? 'late' : /early/.test(b.label) ? 'early' : 'ok';
        return \`<tr><td class="lbl">\${esc(b.label)}</td><td>\${b.n || '-'}</td><td>\${b.n ? pct(b.pct) : '-'}</td><td class="trk-bar-c"><i class="trk-bar \${tone}" style="width:\${Math.round((b.n / max) * 100)}%"></i></td></tr>\`;
      }).join('')}</tbody></table></div></div>\`
    : \`<p class="muted">No \${inb ? 'inbound' : 'outbound'} loads with an appointment in this period, so there is no variance to show (No Appt and Drop &amp; Hook loads aren't rated).</p>\`;
  return \`<div class="trk-dir"><h4 class="trk-h">\${inb ? 'Inbound' : 'Outbound'} trucks</h4>\${tiles(head)}\${variance}</div>\`;
}

/** The whole truck section. opts: { links, open, none } — none = what to show when there are no loads at all. */
export function truckSection(K, cfg, opts = {}) {
  if (!K.n) return opts.none || '';
  const loads = \`<details class="elx-more"\${opts.open ? ' open' : ''}><summary>Every load (\${K.n})</summary><div class="xl-otif-wrap"><table class="xl-otif">\${th(['Date', 'Load', 'In / Out', 'BL / Load #', 'Carrier', 'Appointment', 'Arrived', 'Departed', 'Arrival', 'Variance (min)', 'Hold'])}<tbody>\${
    K.list.map(t => \`<tr><td>\${esc(us(t.date))}</td><td>\${logLink(t.id, opts.links)}</td><td>\${esc(t.direction)}</td><td>\${esc(t.loadNo)}</td><td>\${esc(t.carrier)}</td><td>\${fmtTime(t.appointment)}</td><td>\${fmtTime(t.arrival)}</td><td>\${fmtTime(t.departure)}</td>
      <td class="\${t.status === 'Late' ? 'below fill' : t.status === 'On time' ? 'ok' : ''}">\${esc(t.status)}</td><td>\${t.diff == null ? '' : (t.diff > 0 ? '+' : '') + t.diff}</td><td class="\${t.heldOver === 'Y' ? 'below fill' : ''}">\${t.direction === 'Out' ? mins(t.held) : ''}</td></tr>\`).join('')}</tbody></table></div></details>\`;
  return \`<div class="trk-split">\${block(K.inbound, 'In', cfg)}\${block(K.outbound, 'Out', cfg)}</div>\${loads}
    <p class="xl-foot">Variance = the dock schedule's arrival vs appointment in minutes (+ late, − early). Inbound: arriving early or within \${cfg.onTimeMin} minutes is on time; only late counts against it. Outbound: on time = within ±\${cfg.onTimeMin} minutes. Outbound hold = time in → time out (an early truck’s hold is just its time on site), flagged over \${fmtNum(cfg.holdMin / 60, 1)} hours. Time on site = arrival → departure. No Appt and Drop &amp; Hook loads count in loads and time on site but not in on time or variance.</p>\`;
}`]);

